Vì ngài đã già, không còn chiến nổi.","npc_reply":"Già không có nghĩa chưa biết lúc nên rút kiếm.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_01_D04","npc_id":"HG_TVT_01","npc_name":"Lục Thanh Huyền","faction":"Thanh Vân Tông","kind":"daily","title":"Lời phê của môn sinh","npc_text":"Đệ tử trẻ phê bình quy định của ta. Có nên nghe không?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_TVT_01_D04_A","label":"A","player_text":"Nghe lý do, thử ở quy mô nhỏ và ghi rõ kết quả.","npc_reply":"Cứ thế đi. Quy tắc không phải bia đá bất biến.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_01_D04_B","label":"B","player_text":"Mời họ trình bày trước hội đồng.","npc_reply":"Một cơ hội nói đúng nơi có thể ngăn trăm lời đồn.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_01_D04_C","label":"C","player_text":"Phạt để giữ thể diện chưởng môn.","npc_reply":"Thể diện giữ bằng sợ hãi sẽ sớm đổ.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_02_D01","npc_id":"HG_TVT_02","npc_name":"Tô Nhược Vân","faction":"Thanh Vân Tông","kind":"daily","title":"Sân kiếm vắng","npc_text":"Hôm nay sương dày. Ngươi còn nhìn thấy đường kiếm không?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_TVT_02_D01_A","label":"A","player_text":"Ta sẽ giảm tốc, luyện chuẩn từng thức rồi mới tăng nhanh.","npc_reply":"Ngươi học được cách không thắng chính mình bằng nóng vội.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_02_D01_B","label":"B","player_text":"Ta xin sư tỷ sửa tư thế đứng trước.","npc_reply":"Đứng vững trước, kiếm mới vững.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_02_D01_C","label":"C","player_text":"Ta nhắm mắt chém đại, may ra trúng.","npc_reply":"Đừng lấy đồng môn làm mục tiêu thử vận may.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_02_D02","npc_id":"HG_TVT_02","npc_name":"Tô Nhược Vân","faction":"Thanh Vân Tông","kind":"daily","title":"Dây kiếm tuột nút","npc_text":"Dây buộc chuôi kiếm này đã sờn. Thay dây mới có phải quên dây cũ không?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_TVT_02_D02_A","label":"A","player_text":"Không. Có thể cất dây cũ và dùng dây mới cho an toàn.","npc_reply":"Ta cũng nghĩ thế, chỉ là chưa tự nói ra.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_02_D02_B","label":"B","player_text":"Ta có thể giúp tỷ thắt lại trước buổi luyện.","npc_reply":"Cảm ơn. Thắt vừa thôi, đừng quá chặt.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_02_D02_C","label":"C","player_text":"Đồ cũ vô dụng thì vứt đi ngay.","npc_reply":"Không phải thứ gì cũ cũng hết nghĩa.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_02_D03","npc_id":"HG_TVT_02","npc_name":"Tô Nhược Vân","faction":"Thanh Vân Tông","kind":"daily","title":"Một trận hòa","npc_text":"Nếu đấu kiếm hòa nhau, ngươi muốn làm lại ngay không?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_TVT_02_D03_A","label":"A","player_text":"Ta muốn xem lại từng thế kiếm trước khi tái đấu.","npc_reply":"Được. Học từ trận hòa khó hơn khoe một trận thắng.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_02_D03_B","label":"B","player_text":"Nghỉ một lúc rồi tỷ chỉ cho ta sai ở đâu.","npc_reply":"Ta sẽ nói thật, đừng giận.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_02_D03_C","label":"C","player_text":"Không thắng thì tính là thua, khỏi phân tích.","npc_reply":"Ngươi tự ném bài học đi rồi.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_02_D04","npc_id":"HG_TVT_02","npc_name":"Tô Nhược Vân","faction":"Thanh Vân Tông","kind":"daily","title":"Bước chân cuối hành lang","np