"B","player_text":"Ta hỏi trưởng lão quản lý cấp bản nào được chép.","npc_reply":"Được. Hỏi đúng người đỡ hỏng cả tháng.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_03_D04_C","label":"C","player_text":"Bán bản chép lậu sau lưng ngài.","npc_reply":"Tàng Kinh Các có cửa; ngươi có thể dùng ngay.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_04_D01","npc_id":"HG_TVT_04","npc_name":"Hàn Thiên Minh","faction":"Thanh Vân Tông","kind":"daily","title":"Đường kiếm buổi sớm","npc_text":"Ngươi đến sớm hơn ta hôm nay. Có mục đích gì?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_TVT_04_D01_A","label":"A","player_text":"Muốn xem mình tiến bộ bao nhiêu qua từng thế kiếm.","npc_reply":"Tốt. Ta cũng đến vì thế.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_04_D01_B","label":"B","player_text":"Muốn đấu thử mười chiêu, không phân thắng bại.","npc_reply":"Được. Đừng than nếu thở không ra hơi.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_04_D01_C","label":"C","player_text":"Đến để khoe ngươi sắp bị vượt mặt.","npc_reply":"Khoe bằng miệng thì ai chẳng thắng.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_04_D02","npc_id":"HG_TVT_04","npc_name":"Hàn Thiên Minh","faction":"Thanh Vân Tông","kind":"daily","title":"Kiếm gỗ và kiếm thật","npc_text":"Ngươi thấy buổi tập nào đáng tin hơn?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_TVT_04_D02_A","label":"A","player_text":"Kiếm gỗ để học kỹ thuật, kiếm thật chỉ dùng có bảo hộ đúng quy định.","npc_reply":"Ngươi biết giữ mạng mà vẫn biết luyện.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_04_D02_B","label":"B","player_text":"Ta muốn thử cả hai theo thứ tự tăng khó.","npc_reply":"Được, miễn nhớ giới hạn của mình.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_04_D02_C","label":"C","player_text":"Kiếm thật mới có uy, cứ chém hết lực.","npc_reply":"Thế thì ta khỏi cho ngươi bước lên đài.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_04_D03","npc_id":"HG_TVT_04","npc_name":"Hàn Thiên Minh","faction":"Thanh Vân Tông","kind":"daily","title":"Một lời khen khó nghe","npc_text":"Ngươi thắng ta một thức, định khoe với cả tông sao?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_TVT_04_D03_A","label":"A","player_text":"Ta học được vì có đối thủ mạnh; lần sau chắc ngươi sẽ đổi chiêu.","npc_reply":"Hừ, đừng tưởng ta sẽ dùng lại thế cũ.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_04_D03_B","label":"B","player_text":"Ta muốn nghe ngươi nhận xét lỗi còn lại.","npc_reply":"Được. Lỗi đầu tiên là chân trái chậm nửa nhịp.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_04_D03_C","label":"C","player_text":"Ta hơn ngươi rồi, khỏi cần tập nữa.","npc_reply":"Đánh thắng một thức mà thua cả đầu óc.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_04_D04","npc_id":"HG_TVT_04","npc_name":"Hàn Thiên Minh","faction":"Thanh Vân Tông","kind":"daily","title":"Nút dây trên chuôi","npc_text":"Thấy ta giữ nút dây cũ, ngươi nghĩ ta vướng bận?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_TVT_04_D04_A","label":"A","player_text":"Ta nghĩ đó là điều ngươi muốn nhớ, không phải thứ ta có quyền đánh giá.","npc_reply":"Ngươi ít nhiều biết giữ lời hơn trước.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_04_D04_B","label":"B","player_text":"Nếu ngươi muốn, ta không hỏi thêm.","npc_reply":"Tốt. Có ngày ta sẽ tự kể.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_04_D04_C","label":"C","player_text":"Cứ tháo bỏ, yếu lòng làm chậm kiếm.","npc_reply":"Đi khỏi đây trước khi ta nổi nóng.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_05_D01","npc_id":"HG_TVT_05","npc_name":"Vũ Tiểu Thanh","faction":"Thanh Vân Tông","kind":"daily","title":"Bánh gạo buổi chiều","npc_text":"Mùi này làm ta nhớ ngõ nhỏ gần nhà. Ngươi còn nhớ món ăn quê mình không?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_TVT_05_D01_A","label":"A","player_text":"Ta kể một bữa cơm cũ và hỏi nàng kể lại nếu muốn.","npc_reply":"Nghe chuyện nhỏ của ngươi lại làm ta nhớ được thêm.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_05_D01_B","label":"B","player_text":"Ta xin công thức, biết đâu mọi người cùng nấu.","npc_reply":"Ý hay, một bữa ăn chung sẽ bớt nhớ nhà.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_05_D01_C","label":"C","player_text":"Nhớ làm gì, giờ chỉ cần linh khí.","npc_reply":"Người ta đâu sống chỉ bằng linh khí.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_05_D02","npc_id":"HG_TVT_05","npc_name":"Vũ Tiểu Thanh","faction":"Thanh Vân Tông","kind":"daily","title":"Tên gọi khó phát âm","npc_text":"Tên của một bác mới đến khó phiên âm. Ngươi viết thế nào để không sai?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_TVT_05_D02_A","label":"A","player_text":"Đọc lại cho bác xác nhận, ghi thêm cách gọi và quê quán.","npc_reply":"Chính xác. Một nét sai có thể thành hai người.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_05_D02_B","label":"B","player_text":"Ta sẽ ghi âm phiên âm bằng ký hiệu mình hiểu.","npc_reply":"Miễn có người đọc lại được là tốt.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_05_D02_C","label":"C","player_text":"Viết đại tên dễ nhớ, người ấy không biết đâu.","npc_reply":"Đó là tên của họ, không phải của ngươi.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_05_D03","npc_id":"HG_TVT_05","npc_name":"Vũ Tiểu Thanh","faction":"Thanh Vân Tông","kind":"daily","title":"Giấc mơ có tiếng chuông","npc_text":"Đêm qua ta mơ nghe chuông cửa nhà. Tỉnh dậy chỉ nghe chuông tông môn.","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_TVT_05_D03_A","label":"A","player_text":"Ta có thể ngồi cùng nàng, nếu muốn kể giấc mơ ấy.","npc_reply":"Có người chịu nghe làm ta đỡ sợ tỉnh dậy.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_05_D03_B","label":"B","player_text":"Ta cùng nàng ghi lại ký ức vừa nhớ được.","npc_reply":"Đúng rồi! Ta chưa kịp viết tiếng chuông ấy.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_05_D03_C","label":"C","player_text":"Chỉ là giấc mơ, đừng phiền ta.","npc_reply":"Ta đâu bắt ngươi phải nghe mãi...","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TVT_05_D04","npc_id":"HG_TVT_05","npc_name":"Vũ Tiểu Thanh","faction":"Thanh Vân Tông","kind":"daily","title":"Mực nhòe trên danh sách","npc_text":"Mưa làm nhòe vài dòng tên. Chúng ta làm sao tránh điều này?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_TVT_05_D04_A","label":"A","player_text":"Chép bản dự phòng, bọc chống nước và tách thông tin riêng tư.","npc_reply":"Đúng, một trận mưa không nên làm ai biến mất lần nữa.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TVT_05_D04_B","label":"B","player_text":"Ta giúp hong khô và đọc lại chữ còn thấy.","npc_reply":"Cẩn thận đừng hơ gần lửa quá.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TVT_05_D04_C","label":"C","player_text":"Tên mất rồi thì thôi, ghi người khác.","npc_reply":"Mỗi dòng tên là một người có người chờ.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_01_D01","npc_id":"HG_HSM_01","npc_name":"Huyết Vô Nhai","faction":"Huyết Sát Môn","kind":"daily","title":"Đao cùn trên bậc đá","npc_text":"Ngươi nghĩ thanh đao cùn này còn ích gì?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_HSM_01_D01_A","label":"A","player_text":"Dùng luyện thế và nhắc người cầm biết giới hạn của mình.","npc_reply":"Tốt. Người biết đao cùn mới học cách không ỷ vào sắc bén.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_01_D01_B","label":"B","player_text":"Ta muốn sửa cán để người mới luyện cầm chắc hơn.","npc_reply":"Được. Đừng phí thép làm đẹp chuôi.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_01_D01_C","label":"C","player_text":"Vứt nó, kẻ yếu cầm gì cũng chết.","npc_reply":"Ngươi chưa từng thấy kẻ mạnh chết vì coi thường thứ nhỏ.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_01_D02","npc_id":"HG_HSM_01","npc_name":"Huyết Vô Nhai","faction":"Huyết Sát Môn","kind":"daily","title":"Bữa cơm lính canh","npc_text":"Môn nhân trực đêm cãi nhau vì chia phần thức ăn. Ngươi giải quyết sao?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_HSM_01_D02_A","label":"A","player_text":"Kiểm tra định lượng, người bị thương được phần cần thiết.","npc_reply":"Một đội đói sẽ tự xé nhau trước khi gặp địch.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_01_D02_B","label":"B","player_text":"Ta đưa phần mình cho người thiếu rồi báo quản sự.","npc_reply":"Hào phóng được một đêm, mai nhớ sửa sổ.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_01_D02_C","label":"C","player_text":"Ai cướp nhanh thì ăn, thế mới là Huyết Sát.","npc_reply":"Đừng nhầm mạnh với hỗn loạn.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_01_D03","npc_id":"HG_HSM_01","npc_name":"Huyết Vô Nhai","faction":"Huyết Sát Môn","kind":"daily","title":"Đường sống và đường thắng","npc_text":"Trong chiến trận, ngươi chọn lui một bước hay thắng bằng mọi giá?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_HSM_01_D03_A","label":"A","player_text":"Lui nếu giữ được người và cơ hội