1_B","label":"B","player_text":"Áo của nàng, nàng quyết định.","npc_reply":"Một câu nói ngắn mà dễ nghe.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_02_D01_C","label":"C","player_text":"Đổi hết sang đen cho giống sát thủ đi.","npc_reply":"Ta không mặc áo để giống lời đồn của người khác.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_02_D02","npc_id":"HG_HSM_02","npc_name":"Diệp Hồng Y","faction":"Huyết Sát Môn","kind":"daily","title":"Trạm cứu thương nhỏ","npc_text":"Đứa bé mới đến sợ mỗi khi thấy kiếm. Có cách nào khiến nó yên tâm?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_HSM_02_D02_A","label":"A","player_text":"Cất vũ khí, hạ giọng và để đứa trẻ tự chọn khoảng cách.","npc_reply":"Tốt. Không ép nó phải biết ơn ngay.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_02_D02_B","label":"B","player_text":"Ta đưa đồ chơi và đứng xa để nó quen dần.","npc_reply":"Được. Đừng chạm vào khi nó chưa sẵn lòng.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_02_D02_C","label":"C","player_text":"Bảo nó phải quen máu, ở đây là Huyết Sát.","npc_reply":"Trẻ con không sinh ra để luyện gan cho ngươi.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_02_D03","npc_id":"HG_HSM_02","npc_name":"Diệp Hồng Y","faction":"Huyết Sát Môn","kind":"daily","title":"Tin đồn trong quán","npc_text":"Người ở chợ lại kể ta giết cả một làng. Ngươi nghe thì làm gì?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_HSM_02_D03_A","label":"A","player_text":"Hỏi chứng cứ và không kể lại lời đồn như sự thật.","npc_reply":"Lâu lắm rồi mới có người không vội kết án ta.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_02_D03_B","label":"B","player_text":"Nếu nàng muốn, ta giúp tìm nơi tin ấy bắt đầu.","npc_reply":"Không cần biến mọi lời đồn thành cuộc săn.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_02_D03_C","label":"C","player_text":"Tin có lửa mới có khói, chắc nàng đã làm.","npc_reply":"Ngươi chỉ thích một câu chuyện khiến mình sợ.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_02_D04","npc_id":"HG_HSM_02","npc_name":"Diệp Hồng Y","faction":"Huyết Sát Môn","kind":"daily","title":"Buổi đêm không ngủ","npc_text":"Có đêm ta nghe lại tiếng cháy nhà cũ. Ngươi sẽ khuyên thế nào?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_HSM_02_D04_A","label":"A","player_text":"Nếu muốn, ta ngồi cạnh một lúc, không bắt nàng kể.","npc_reply":"Sự im lặng của ngươi không làm ta khó chịu.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_02_D04_B","label":"B","player_text":"Ta chuẩn bị trà an thần và để nàng tự quyết có dùng không.","npc_reply":"Được. Ta sẽ xem trước thành phần.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_02_D04_C","label":"C","player_text":"Tập giết nhiều hơn thì sẽ hết mơ.","npc_reply":"Vết thương không cần thêm máu để lành.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_03_D01","npc_id":"HG_HSM_03","npc_name":"A Cửu","faction":"Huyết Sát Môn","kind":"daily","title":"Bước tập đầu tiên","npc_text":"Ta vừa giữ được thế tấn lâu hơn hôm qua một nhịp. Có đáng kể không?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_HSM_03_D01_A","label":"A","player_text":"Rất đáng. Ngươi có thể ghi tiến bộ mỗi ngày.","npc_reply":"Ta sẽ làm vậy. Nhìn thấy từng bước nhỏ dễ chịu thật.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_03_D01_B","label":"B","player_text":"Ta đứng canh thời gian cho lần luyện sau.","npc_reply":"Có người đếm giúp chắc ta đỡ run.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_03_D01_C","label":"C","player_text":"Một nhịp chẳng nghĩa gì, bỏ đi.","npc_reply":"Ta biết mình chậm, nhưng vẫn muốn tiến.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_03_D02","npc_id":"HG_HSM_03","npc_name":"A Cửu","faction":"Huyết Sát Môn","kind":"daily","title":"Bát cơm chia đôi","npc_text":"Bạn cùng phòng bị phạt không có phần ăn. Ta nên chia của mình?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_HSM_03_D02_A","label":"A","player_text":"Chia khi đủ cho cả hai rồi hỏi lý do phạt, tránh lặp lại.","npc_reply":"Cảm ơn. Ta sợ giúp một lần rồi hắn lại bị đánh.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_03_D02_B","label":"B","player_text":"Ta mang thêm nước và nhờ người phụ trách kiểm tra.","npc_reply":"Được. Ta sẽ không để hắn đói một mình.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_03_D02_C","label":"C","player_text":"Giữ hết, yếu thì tự chịu.","npc_reply":"Ta từng được người khác chia cơm, không quên nổi.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_03_D03","npc_id":"HG_HSM_03","npc_name":"A Cửu","faction":"Huyết Sát Môn","kind":"daily","title":"Đêm nhìn trời","npc_text":"Ngươi nghĩ em gái ta có đang nhìn cùng một vầng trăng?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_HSM_03_D03_A","label":"A","player_text":"Có thể. Hy vọng ấy đáng giữ, nhưng ta sẽ cùng tìm manh mối thật.","npc_reply":"Ta cần cả hai: hy vọng và một con đường.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_03_D03_B","label":"B","player_text":"Ta có thể hỏi Hội Quy Hương giúp thêm lần nữa.","npc_reply":"Nếu ngươi không phiền... cảm ơn.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_03_D03_C","label":"C","player_text":"Chắc nó quên ngươi rồi.","npc_reply":"Đừng đoán điều đáng sợ nhất của ta như trò đùa.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_03_D04","npc_id":"HG_HSM_03","npc_name":"A Cửu","faction":"Huyết Sát Môn","kind":"daily","title":"Vết bầm mới","npc_text":"Ta giấu vết thương vì sợ mất suất luyện. Ngươi có nói với quản sự không?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_HSM_03_D04_A","label":"A","player_text":"Ta đưa ngươi đi kiểm tra và cùng giải thích với quản sự.","npc_reply":"Ta sợ bị đuổi, nhưng giấu nữa chỉ đau hơn.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_03_D04_B","label":"B","player_text":"Ta giúp ngươi xin nghỉ buổi này rồi luyện bù.","npc_reply":"Cũng được. Ta không muốn bỏ hẳn.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_03_D04_C","label":"C","player_text":"Cứ cắn răng luyện tiếp cho mạnh.","npc_reply":"Ngươi không thấy ta sắp không đứng nổi sao?","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_04_D01","npc_id":"HG_HSM_04","npc_name":"Tần Vô Sinh","faction":"Huyết Sát Môn","kind":"daily","title":"Một dòng sổ nợ","npc_text":"Có người quên ngày trả nợ. Ngươi nghĩ ta nên nhắc một lần hay trừng phạt ngay?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_HSM_04_D01_A","label":"A","player_text":"Nhắc theo điều khoản, ghi rõ và cho cơ hội giải trình.","npc_reply":"Được. Kẻ biết quy trình có thể quản sổ.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_04_D01_B","label":"B","player_text":"Ta muốn kiểm tra xem hắn thật quên hay cố ý.","npc_reply":"Sự khác nhau ấy đáng một trang giấy.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_04_D01_C","label":"C","player_text":"Cắt linh căn hắn cho mọi người sợ.","npc_reply":"Một biện pháp quá tốn kém để thu món nợ nhỏ.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_04_D02","npc_id":"HG_HSM_04","npc_name":"Tần Vô Sinh","faction":"Huyết Sát Môn","kind":"daily","title":"Đệ tử thắng cược","npc_text":"Nếu một môn sinh thắng quá dễ trong trận cược, ngươi nghi hắn gian lận chứ?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_HSM_04_D02_A","label":"A","player_text":"Kiểm sổ đặt cược và chứng cứ trước khi kết luận.","npc_reply":"Ta không thích mất tiền vì phán đoán sai.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_04_D02_B","label":"B","player_text":"Ta theo dõi vài trận nữa để xem bất thường.","npc_reply":"Được. Kiên nhẫn là loại vốn hiếm.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_04_D02_C","label":"C","player_text":"Tịch thu hết tiền hắn vì ta không thích thua.","npc_reply":"Kẻ lấy quyền làm thói quen rồi sẽ bị quyền nuốt.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_04_D03","npc_id":"HG_HSM_04","npc_name":"Tần Vô Sinh","faction":"Huyết Sát Môn","kind":"daily","title":"Lãi của một món ơn","npc_text":"Ta cứu ngươi một lần, ngươi định trả ơn thế nào?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_HSM_04_D03_A","label":"A","player_text":"Ta trả đúng việc đã hứa, không hứa bán cả đời.","npc_reply":"Ngươi khó mặc cả, nhưng lời nói đáng ghi.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_04_D03_B","label":"B","player_text":"Ta hỏi ông muốn trao đổi điều gì rõ ràng.","npc_reply":"Được. Sổ nợ ghét lời mơ hồ.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_04_D03_C","label":"C","player_text":"Ta xin làm bất kỳ việc gì kể cả hại vô tội.","npc_reply":"Một hợp đồng dễ ký thường dễ phản bội.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_04_D04","npc_id":"HG_HSM_04","npc_name":"Tần Vô Sinh","faction":"Huyết Sát Môn","kind":"daily","title":"Quyền và sự kính trọng","npc_text":"Kẻ dưới có nên được phép phản biện trưởng lão?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_HSM_04_D04_A","label":"A","player_text":"Có, nếu có chứng cứ và chịu trách nhiệm lời mình nói.","npc_reply":"Ngươi dám cho phép thứ có thể chống lại mình, thú vị.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_04_D04_B","label":"B","player_text":"Nên có nơi trình bày kín để tránh hỗn loạn.","npc_reply":"Ta thích cách kiểm soát đường thông tin ấy.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_04_D04_C","label":"C","player_text":"Không. Quyền lực không bao giờ sai.","npc_reply":"Ngay cả ta cũng không dám tin câu đó.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_05_D01","npc_id":"HG_HSM_05","npc_name":"Hắc Đồng","faction":"Huyết Sát Môn","kind":"daily","title":"Ba tiếng búa","npc_text":"Nghe ba tiếng búa này, ngươi thấy chỗ nào của thỏi thép chưa đều?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_HSM_05_D01_A","label":"A","player_text":"Tiếng cuối đục hơn; có thể còn tạp chất gần mép.","npc_reply":"Tai ngươi bắt đầu biết nghe thép rồi.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_05_D01_B","label":"B","player_text":"Ta chưa phân biệt nổi, xin ông gõ lại chậm hơn.","npc_reply":"Không biết mà hỏi thì học được.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_05_D01_C","label":"C","player_text":"Tiếng nào cũng như nhau, mất công nghe.","npc_reply":"Ngươi dùng tai như một cái móc treo đấy.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_05_D02","npc_id":"HG_HSM_05","npc_name":"Hắc Đồng","faction":"Huyết Sát Môn","kind":"daily","title":"Tay chai và tay mềm","npc_text":"Tay người mới rèn hay phồng rộp. Ngươi sẽ dạy họ làm gì trước?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_HSM_05_D02_A","label":"A","player_text":"Tập thao tác đúng, dùng bảo hộ và nghỉ khi cần.","npc_reply":"Da mới rồi sẽ dày, gân đứt thì lâu lành.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_05_D02_B","label":"B","player_text":"Ta chỉnh cán búa cho vừa tay học trò.","npc_reply":"Đúng. Dụng cụ không nên bắt người khổ vô ích.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_05_D02_C","label":"C","player_text":"Cứ đánh đến bật máu mới thành thợ.","npc_reply":"Đồ rèn tốt không cần thợ mang tật.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_05_D03","npc_id":"HG_HSM_05","npc_name":"Hắc Đồng","faction":"Huyết Sát Môn","kind":"daily","title":"Lưỡi kiếm nói thật","npc_text":"Vết gãy cho biết gì về người cầm kiếm?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_HSM_05_D03_A","label":"A","player_text":"Cho biết lực và thói quen, nhưng chưa đủ kết tội một con người.","npc_reply":"Hay. Kim loại kể phần việc nó chứng kiến, không kể tất cả.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_05_D03_B","label":"B","player_text":"Ta muốn so với nhật ký trận chiến.","npc_reply":"Một người chịu đối chứng đáng được cầm búa.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_05_D03_C","label":"C","player_text":"Kiếm gãy thì chắc chủ nhân hèn nhát.","npc_reply":"Có kiếm gãy vì đứng che cho người khác.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_HSM_05_D04","npc_id":"HG_HSM_05","npc_name":"Hắc Đồng","faction":"Huyết Sát Môn","kind":"daily","title":"Nhiệt lò và tiếng mưa","npc_text":"Trời mưa, lò nguội nhanh. Ngươi đổi cách rèn thế nào?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_HSM_05_D04_A","label":"A","player_text":"Điều chỉnh chu kỳ nung theo nhiệt thực tế, thử mẫu trước.","npc_reply":"Đúng. Lửa không quan tâm dự định của thợ.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_HSM_05_D04_B","label":"B","player_text":"Ta che gió, kiểm lại ống dẫn khí cho an toàn.","npc_reply":"Được. Lo lò trước, lo thành phẩm sau.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_HSM_05_D04_C","label":"C","player_text":"Cứ tăng lửa hết mức, thép nào chẳng chảy.","npc_reply":"Cách ấy chỉ chắc chảy mái xưởng.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_01_D01","npc_id":"HG_VDC_01","npc_name":"Dược Vô Trần","faction":"Vạn Dược Cốc","kind":"daily","title":"Lá khô trong dược viện","npc_text":"Một lá thuốc đã héo có còn dùng được không?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_VDC_01_D01_A","label":"A","player_text":"Phải xét hoạt chất, tình trạng bảo quản và mục đích, không đoán.","npc_reply":"Ngươi biết thuốc không chỉ là hình dạng.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_01_D01_B","label":"B","player_text":"Ta xin đan sư có kinh nghiệm kiểm tra trước.","npc_reply":"Thận trọng đúng lúc là đáng quý.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_01_D01_C","label":"C","player_text":"Cứ trộn vào cho đủ cân.","npc_reply":"Đó không phải cách cứu người.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_01_D02","npc_id":"HG_VDC_01","npc_name":"Dược Vô Trần","faction":"Vạn Dược Cốc","kind":"daily","title":"Bản ghi dược tính","npc_text":"Hai quyển dược điển ghi tác dụng khác nhau. Ngươi tin quyển nào?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_VDC_01_D02_A","label":"A","player_text":"Đối chiếu nguồn và thí nghiệm đã được xác minh, ghi chỗ bất định.","npc_reply":"Lời ''chưa đủ chứng cứ'' cứu được nhiều mạng.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_01_D02_B","label":"B","player_text":"Ta hỏi nhóm trồng và nhóm dùng thuốc riêng.","npc_reply":"Được. Mỗi người thấy một mặt của cây thuốc.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_01_D02_C","label":"C","player_text":"Quyển đắt tiền chắc đúng hơn.","npc_reply":"Giá sách không quyết định dược tính.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_01_D03","npc_id":"HG_VDC_01","npc_name":"Dược Vô Trần","faction":"Vạn Dược Cốc","kind":"daily","title":"Người bệnh ở hiên","npc_text":"Có người muốn hỏi tuổi thọ còn lại, nhưng ta chưa đoán chắc. Nói thế nào?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_VDC_01_D03_A","label":"A","player_text":"Nói rõ điều đã biết và chưa biết, đồng thời đề xuất chăm sóc.","npc_reply":"Ta cần học cách không trốn câu hỏi ấy.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_01_D03_B","label":"B","player_text":"Ta ở cạnh để người bệnh được hỏi tiếp.","npc_reply":"Đôi khi đó là sự hỗ trợ lớn nhất.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_01_D03_C","label":"C","player_text":"Cứ hứa sống trăm năm để họ vui.","npc_reply":"Một lời hứa giả có thể cướp đi thời gian chuẩn bị của họ.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_01_D04","npc_id":"HG_VDC_01","npc_name":"Dược Vô Trần","faction":"Vạn Dược Cốc","kind":"daily","title":"Mùi đan lò","npc_text":"Một lò đan thành công khiến môn nhân reo hò. Ngươi làm gì ngay sau đó?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_VDC_01_D04_A","label":"A","player_text":"Kiểm tra chất lượng, ghi mẻ và theo dõi tác dụng ngoài dự kiến.","npc_reply":"Vui vẫn phải ghi chép. Đúng thế.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_01_D04_B","label":"B","player_text":"Ta chúc mừng rồi dọn sạch khu làm việc.","npc_reply":"Một nơi sạch là lời cảm ơn thợ đan.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_01_D04_C","label":"C","player_text":"Bán ngay trước khi có kết quả kiểm tra.","npc_reply":"Ta không dùng người mua thay phòng thử nghiệm.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_02_D01","npc_id":"HG_VDC_02","npc_name":"Linh Nhi","faction":"Vạn Dược Cốc","kind":"daily","title":"Mầm cây ngày nắng","npc_text":"Huynh xem mầm này mọc nhanh quá! Có nên thêm thật nhiều linh dịch không?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_VDC_02_D01_A","label":"A","player_text":"Cứ đúng liều tưới và theo dõi phản ứng từng ngày.","npc_reply":"Muội lại suýt làm quá tay rồi.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_02_D01_B","label":"B","player_text":"Ta giúp muội ghi độ ẩm đất vào sổ.","npc_reply":"Hay! Thế là có thể so ngày nắng với ngày mưa.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_02_D01_C","label":"C","player_text":"Đổ hết bình, càng nhiều càng tốt.","npc_reply":"Không được, rễ sẽ úng mất!","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_02_D02","npc_id":"HG_VDC_02","npc_name":"Linh Nhi","faction":"Vạn Dược Cốc","kind":"daily","title":"Bữa sáng của dược đồng","npc_text":"Muội hái thuốc quên ăn, giờ chóng mặt quá. Có nên làm tiếp?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_VDC_02_D02_A","label":"A","player_text":"Ăn nhẹ, nghỉ rồi mới vào khu nguy hiểm.","npc_reply":"Có huynh nhắc nên muội mới nhớ thân mình cũng cần chăm.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_02_D02_B","label":"B","player_text":"Ta trông giỏ thuốc cho muội dùng bữa.","npc_reply":"Cảm ơn! Muội quay lại ngay.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_02_D02_C","label":"C","player_text":"Cố làm tới khi ngất, mới là chăm chỉ.","npc_reply":"Huynh nói vậy nghe đáng sợ quá.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_02_D03","npc_id":"HG_VDC_02","npc_name":"Linh Nhi","faction":"Vạn Dược Cốc","kind":"daily","title":"Nhãn lọ bị nhòe","npc_text":"Chữ trên hai lọ thuốc bị nhòe. Muội nghĩ theo mùi vẫn đoán được.","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_VDC_02_D03_A","label":"A","player_text":"Niêm phong cả hai, kiểm mẫu theo quy trình, không