C","player_text":"Nối đại các điểm thành hình đẹp hơn.","npc_reply":"Đẹp không phải đồng nghĩa hoạt động.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_03_D04","npc_id":"HG_VDC_03","npc_name":"Tạ Thiên Cơ","faction":"Vạn Dược Cốc","kind":"daily","title":"Bài giảng hụt người nghe","npc_text":"Ta vừa nói suốt một canh giờ. Ngươi hiểu được bao nhiêu?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_VDC_03_D04_A","label":"A","player_text":"Ba nguyên tắc; phần không rõ ta sẽ hỏi lại từng ý.","npc_reply":"Tốt, người không giả hiểu là học trò quý.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_03_D04_B","label":"B","player_text":"Ta xin mượn bản vẽ để học thêm.","npc_reply":"Nhớ không mang vào gần lửa.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_03_D04_C","label":"C","player_text":"Ta hiểu hết, khỏi kiểm tra, dù chưa nghe đầu câu.","npc_reply":"Nói dối trước một trận sư còn nguy hiểm hơn sai phép.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_04_D01","npc_id":"HG_VDC_04","npc_name":"Bạch Tử Yên","faction":"Vạn Dược Cốc","kind":"daily","title":"Bàn tay rửa lâu","npc_text":"Ta rửa tay sau mỗi ca. Có người bảo ta quá cẩn trọng. Ngươi nghĩ sao?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_VDC_04_D01_A","label":"A","player_text":"Kiểm soát vệ sinh và quy trình an toàn đáng duy trì.","npc_reply":"Ít nhất có người hiểu vì sao ta không bớt bước ấy.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_04_D01_B","label":"B","player_text":"Ta muốn học quy trình vào phòng thuốc.","npc_reply":"Đến đúng giờ, ta sẽ hướng dẫn.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_04_D01_C","label":"C","player_text":"Rửa cho có lệ, tu sĩ có linh khí rồi.","npc_reply":"Linh khí không thay mọi biện pháp kiểm soát nhiễm bẩn.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_04_D02","npc_id":"HG_VDC_04","npc_name":"Bạch Tử Yên","faction":"Vạn Dược Cốc","kind":"daily","title":"Biên bản thiếu chữ ký","npc_text":"Một bản thử đan thiếu người phê duyệt nhưng kết quả tốt. Xếp nó ở đâu?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_VDC_04_D02_A","label":"A","player_text":"Giữ làm dữ liệu, đánh dấu chưa hợp lệ và không cấp dùng.","npc_reply":"Không xóa kết quả, không giả quy trình. Đúng.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_04_D02_B","label":"B","player_text":"Ta xin người phụ trách làm rõ tại sao thiếu.","npc_reply":"Cần tìm lý do, không chỉ đi xin một chữ ký.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_04_D02_C","label":"C","player_text":"Tự ký hộ, chẳng ai kiểm tra đâu.","npc_reply":"Ngươi không được chạm vào hồ sơ của ta nữa.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_04_D03","npc_id":"HG_VDC_04","npc_name":"Bạch Tử Yên","faction":"Vạn Dược Cốc","kind":"daily","title":"Một lời xin lỗi quá muộn","npc_text":"Thầy thuốc phạm sai lầm rồi xin lỗi. Điều gì khiến lời xin lỗi có ý nghĩa?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_VDC_04_D03_A","label":"A","player_text":"Nhận trách nhiệm, hỗ trợ người bị hại và sửa quy trình.","npc_reply":"Xin lỗi không hoàn lại mạng người, nhưng trách nhiệm không thể bỏ.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_04_D03_B","label":"B","player_text":"Ghi sự cố đầy đủ để người sau tránh lặp lại.","npc_reply":"Đó là một phần cần có.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_04_D03_C","label":"C","player_text":"Xin lỗi xong thì xóa hồ sơ.","npc_reply":"Đó là che giấu, không phải sửa sai.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_04_D04","npc_id":"HG_VDC_04","npc_name":"Bạch Tử Yên","faction":"Vạn Dược Cốc","kind":"daily","title":"Y quy giữa đêm","npc_text":"Đệ tử trẻ than quy tắc nhiều làm chậm luyện đan. Ngươi nói sao?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_VDC_04_D04_A","label":"A","player_text":"Phân biệt bước bảo vệ bệnh nhân và thủ tục thừa, sửa bằng chứng cứ.","npc_reply":"Ta không phản đối cải tiến, chỉ phản đối coi sinh mạng là vật cản.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_04_D04_B","label":"B","player_text":"Ta giúp họ học quy trình cho quen.","npc_reply":"Tốt. Hiểu luật rồi hãy đề nghị sửa.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_04_D04_C","label":"C","player_text":"Cứ bỏ hết, tiến cảnh quan trọng hơn.","npc_reply":"Ta đã thấy điều ấy dẫn đến đâu.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_05_D01","npc_id":"HG_VDC_05","npc_name":"Hứa Mặc","faction":"Vạn Dược Cốc","kind":"daily","title":"Cây bút hết mực","npc_text":"Ta nhớ tiếng bút bi trên giấy hơn tiếng đan lò. Ngươi thấy kỳ quặc không?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_VDC_05_D01_A","label":"A","player_text":"Không. Có khi thói quen ghi chép đã cứu nhiều mạng.","npc_reply":"Đúng là thứ nhỏ ta không muốn mất.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_05_D01_B","label":"B","player_text":"Ta có bút phục chế, muốn thử xem hợp tay không?","npc_reply":"Hay đấy! Đầu bút hơi cứng nhưng dùng được.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_05_D01_C","label":"C","player_text":"Linh căn yếu nên ngươi mới bám mấy thứ phàm.","npc_reply":"Một tờ bệnh án có thể cứu người mà không cần linh căn mạnh.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_05_D02","npc_id":"HG_VDC_05","npc_name":"Hứa Mặc","faction":"Vạn Dược Cốc","kind":"daily","title":"Hai thuật ngữ một triệu chứng","npc_text":"Đan sư gọi là khí nghịch, ta gọi là khó thở. Ngươi sẽ ghi vào hồ sơ thế nào?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_VDC_05_D02_A","label":"A","player_text":"Ghi mô tả khách quan và cả hai giả thuyết, tách điều đã đo.","npc_reply":"Đúng rồi. Người đọc sau biết đâu tìm ra đáp án.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_05_D02_B","label":"B","player_text":"Ta làm bảng đối chiếu thuật ngữ.","npc_reply":"Cần đấy. Hai người nói khác không có nghĩa một người sai.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_05_D02_C","label":"C","player_text":"Xóa một bên để khỏi rắc rối.","npc_reply":"Như vậy ta vừa bỏ mất nửa thông tin.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_05_D03","npc_id":"HG_VDC_05","npc_name":"Hứa Mặc","faction":"Vạn Dược Cốc","kind":"daily","title":"Thầy thuốc cũng mệt","npc_text":"Ca trực dài làm ta nhìn chữ nhòe đi. Ngươi sẽ nhắc điều gì?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_VDC_05_D03_A","label":"A","player_text":"Đổi ca, nghỉ ngắn an toàn và bàn giao rõ ca nguy cấp.","npc_reply":"Cảm ơn. Người cứu bệnh nhân cũng cần được giữ tỉnh táo.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_05_D03_B","label":"B","player_text":"Ta giúp chép bàn giao cho ca sau.","npc_reply":"Được, đọc lại để chắc không thiếu.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_05_D03_C","label":"C","player_text":"Cứ cố đến ngất, bác sĩ tốt phải thế.","npc_reply":"Một bác sĩ ngất thêm một bệnh nhân thôi.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_VDC_05_D04","npc_id":"HG_VDC_05","npc_name":"Hứa Mặc","faction":"Vạn Dược Cốc","kind":"daily","title":"Bảng trắng thay bệnh án","npc_text":"Một trưởng lão không thích ghi hồ sơ vì ''ta nhớ hết''. Ngươi sẽ làm gì?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_VDC_05_D04_A","label":"A","player_text":"Đề nghị mẫu ghi nhanh đủ thông tin tối thiểu và kiểm chứng.","npc_reply":"Ta muốn giải pháp khiến người bận cũng ghi được.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_VDC_05_D04_B","label":"B","player_text":"Ta xin được ghi thay và để ông xác nhận.","npc_reply":"Tốt. Có chữ ký xác nhận càng rõ.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_VDC_05_D04_C","label":"C","player_text":"Không cần ghi, người giỏi không bao giờ quên.","npc_reply":"Người giỏi càng biết trí nhớ có thể sai.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TL_01_D01","npc_id":"HG_TL_01","npc_name":"Trần Minh","faction":"Trung lập","kind":"daily","title":"Một bảng biểu kín ô","npc_text":"Ta từng tưởng Excel là thứ đáng sợ nhất đời. Giờ ngươi nhìn danh sách này xem.","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_TL_01_D01_A","label":"A","player_text":"Ta giúp anh chia thành mục đã xác minh và mục còn chờ.","npc_reply":"May quá. Mình cần hệ thống, không cần thêm một đống giấy.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TL_01_D01_B","label":"B","player_text":"Ta sẽ đánh số và làm bản sao.","npc_reply":"Có người phụ là nhẹ cả người.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TL_01_D01_C","label":"C","player_text":"Đốt đi cho đỡ việc, tìm ai gặp thì gặp.","npc_reply":"Những cái tên đó không phải việc thừa.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TL_01_D02","npc_id":"HG_TL_01","npc_name":"Trần Minh","faction":"Trung lập","kind":"daily","title":"Người mới tới hội","npc_text":"Một bác lớn tuổi xin tham gia tìm thân, nhưng không biết chữ nơi này. Làm sao giúp?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_TL_01_D02_A","label":"A","player_text":"Có người đọc/ghi giúp, xác nhận lại bằng tiếng bác hiểu.","npc_reply":"Ta cần một mẫu đăng ký không bỏ người ít học.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TL_01_D02_B","label":"B","player_text":"Ta hướng dẫn bác nhận dấu hiệu hội và người phụ trách.","npc_reply":"Hay, đỡ để bác lạc giữa đám đông.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TL_01_D02_C","label":"C","player_text":"Không đọc được thì không cho đăng ký.","npc_reply":"Hội này mở vì người lạc đường, không phải vì người biết chữ.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TL_01_D03","npc_id":"HG_TL_01","npc_name":"Trần Minh","faction":"Trung lập","kind":"daily","title":"Bữa cơm tập thể","npc_text":"Một vài người bảo họ chẳng muốn về nữa. Có nên xóa tên họ khỏi Hội Quy Hương?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_TL_01_D03_A","label":"A","player_text":"Hỏi họ có muốn tạm ẩn tên, vẫn giữ quyền đổi quyết định.","npc_reply":"Một lựa chọn hôm nay không nên thành xiềng xích.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TL_01_D03_B","label":"B","player_text":"Ta đánh dấu ''chưa muốn về'', không ép họ.","npc_reply":"Đúng. Hội phải tôn trọng quyết định ấy.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TL_01_D03_C","label":"C","player_text":"Ai không muốn về là phản bội, xóa hết.","npc_reply":"Anh lập hội để tìm nhà, không lập để phán ai yêu quê hơn.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TL_01_D04","npc_id":"HG_TL_01","npc_name":"Trần Minh","faction":"Trung lập","kind":"daily","title":"Bản tin một dòng","npc_text":"Hôm nay chẳng có tin mới. Ta có nên đăng ''không có gì'' không?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_TL_01_D04_A","label":"A","player_text":"Có. Báo trạng thái và thời gian cập nhật để mọi người khỏi chờ tin giả.","npc_reply":"Một bản tin thật dù trống vẫn đáng tin.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TL_01_D04_B","label":"B","player_text":"Ta giúp tổng hợp những đầu mối đang được xác minh.","npc_reply":"Được. Đừng gọi chúng là đã tìm thấy.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TL_01_D04_C","label":"C","player_text":"Bịa một tin vui để hội đỡ nản.","npc_reply":"Một lời nói dối đủ làm cả hội mất uy tín.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TL_02_D01","npc_id":"HG_TL_02","npc_name":"Bạch Tiểu Ngư","faction":"Trung lập","kind":"daily","title":"Buổi sáng mở sạp","npc_text":"Khách đầu tiên hôm nay chỉ nhìn mà không mua. Ngươi nghĩ ta nên làm gì?","min_affection":0,"pool_index":1,"choices":[{"choice_id":"HG_TL_02_D01_A","label":"A","player_text":"Cho họ xem giá và công dụng, không ép mua.","npc_reply":"Đúng. Người nhìn hôm nay có thể trở lại ngày mai.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TL_02_D01_B","label":"B","player_text":"Ta giúp cô xếp mẫu hàng dễ xem hơn.","npc_reply":"Hữu ích hơn cả lời chúc mua may.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TL_02_D01_C","label":"C","player_text":"Đuổi họ đi vì không có tiền.","npc_reply":"Khách tới sạp ta không phải kẻ bị xét túi.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TL_02_D02","npc_id":"HG_TL_02","npc_name":"Bạch Tiểu Ngư","faction":"Trung lập","kind":"daily","title":"Món hàng bị trả","npc_text":"Khách dùng một ngày rồi trả vì hàng có lỗi. Ta nên xử lý sao?","min_affection":0,"pool_index":2,"choices":[{"choice_id":"HG_TL_02_D02_A","label":"A","player_text":"Kiểm tra lỗi, công khai điều kiện đổi trả và sửa lô hàng.","npc_reply":"Giữ được chữ tín còn lời hơn bán một món lỗi.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TL_02_D02_B","label":"B","player_text":"Ta giúp ghi ngày bán và tình trạng hàng.","npc_reply":"Cần đấy. Sổ sách giúp khỏi cãi nhau.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TL_02_D02_C","label":"C","player_text":"Cứ bảo do khách vụng, khỏi kiểm tra.","npc_reply":"Một lời phủi tay có thể đuổi mười khách.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TL_02_D03","npc_id":"HG_TL_02","npc_name":"Bạch Tiểu Ngư","faction":"Trung lập","kind":"daily","title":"Giá mùa mưa","npc_text":"Mưa làm tuyến hàng xa bị cắt. Nếu giá tăng, ta nên thông báo thế nào?","min_affection":0,"pool_index":3,"choices":[{"choice_id":"HG_TL_02_D03_A","label":"A","player_text":"Niêm giá mới và lý do, giữ suất tối thiểu cho người cần thuốc.","npc_reply":"Ta muốn lời, nhưng không muốn người bệnh chết trước quầy.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TL_02_D03_B","label":"B","player_text":"Ta giúp phân loại hàng khan hiếm cần ưu tiên.","npc_reply":"Có lý. Không thể gom tất cả vào một rổ.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TL_02_D03_C","label":"C","player_text":"Giấu hàng, tung tin sắp hết để ép giá.","npc_reply":"Làm thế nhanh giàu, cũng nhanh bị cả chợ tẩy chay.","affection_delta":-4,"trust_delta":-2}],"repeatable":true,"one_time_per_life":false,"story_reward":false},{"scene_id":"HG_TL_02_D04","npc_id":"HG_TL_02","npc_name":"Bạch Tiểu Ngư","faction":"Trung lập","kind":"daily","title":"Đếm tiền bằng hai tay","npc_text":"Nếu khách trả bằng Linh Thạch thượng phẩm, ngươi có đổi theo giá ta ghi không?","min_affection":0,"pool_index":4,"choices":[{"choice_id":"HG_TL_02_D04_A","label":"A","player_text":"Theo tỷ giá công khai: 1 thượng phẩm bằng 1.000 hạ phẩm, kiểm đủ rồi giao.","npc_reply":"Tốt! Không ai cãi nếu sổ rõ ràng.","affection_delta":5,"trust_delta":1},{"choice_id":"HG_TL_02_D04_B","label":"B","player_text":"Ta yêu cầu ghi rõ tiền thối và phí nếu có.","npc_reply":"Đúng. Tiền lẻ là nơi dễ nảy tranh chấp nhất.","affection_delta":3,"trust_delta":2},{"choice_id":"HG_TL_02_D04_C","label":"C","player_text":"Tỷ giá tùy miệng người bán, hôm nay ta thích một giá khác.","npc_reply":"Cách ấy còn nhanh phá thươn