gọi đan sư trực và Hứa Mặc, giữ an toàn cho bệnh nhân, không tự tăng liều.","npc_reply":"Muội hoảng quá... Cảm ơn huynh nhắc làm đúng việc.","affection_delta":9,"trust_delta":5},{"choice_id":"HG_VDC_02_E02_B","label":"B","player_text":"Ta đi tìm hồ sơ dùng thuốc mới nhất cho thầy thuốc.","npc_reply":"Có ghi chép chắc họ sẽ biết cần làm gì.","affection_delta":4,"trust_delta":2},{"choice_id":"HG_VDC_02_E02_C","label":"C","player_text":"Cho uống hết Thanh Hồn Quả để chữa dứt điểm.","npc_reply":"Không! Quả ấy chỉ giúp ổn định thần hồn.","affection_delta":-6,"trust_delta":-3}],"repeatable":false,"one_time_per_life":true,"story_reward":false},{"scene_id":"HG_VDC_03_E01","npc_id":"HG_VDC_03","npc_name":"Tạ Thiên Cơ","faction":"Vạn Dược Cốc","kind":"event","title":"Mô hình trận tự xoay","npc_text":"[Sự kiện] Một mô hình trận bàn cũ tự phát sáng, học trò tò mò định chạm vào.","min_affection":20,"pool_index":1,"choices":[{"choice_id":"HG_VDC_03_E01_A","label":"A","player_text":"Ta cách ly khu vực, cắt nguồn cấp được phép và gọi Tạ Thiên Cơ.","npc_reply":"Phản xạ tốt. Đừng để tay tò mò đi trước đầu.","affection_delta":9,"trust_delta":5},{"choice_id":"HG_VDC_03_E01_B","label":"B","player_text":"Ta ghi thứ tự điểm sáng từ khoảng cách an toàn.","npc_reply":"Có dữ liệu rồi ta mới xét được.","affection_delta":4,"trust_delta":2},{"choice_id":"HG_VDC_03_E01_C","label":"C","player_text":"Ta thử cắm tay vào luồng sáng xem có cơ duyên.","npc_reply":"Ngươi xem thân thể như que thử trận sao?","affection_delta":-6,"trust_delta":-3}],"repeatable":false,"one_time_per_life":true,"story_reward":false},{"scene_id":"HG_VDC_03_E02","npc_id":"HG_VDC_03","npc_name":"Tạ Thiên Cơ","faction":"Vạn Dược Cốc","kind":"event","title":"Khối đá cổ rạn nứt","npc_text":"[Sự kiện] Mảnh đá ghi cổ văn rơi xuống đất, một góc ký hiệu bị mẻ.","min_affection":50,"pool_index":2,"choices":[{"choice_id":"HG_VDC_03_E02_A","label":"A","player_text":"Ta ghi hình dạng, giữ mảnh vỡ và không đoán ký tự còn thiếu.","npc_reply"