"label":"B","player_text":"Ta ghi tên người ra vào rồi đi tìm trưởng lão.","npc_reply":"Tốt, đừng tự đối đầu một mình.","affection_delta":4,"trust_delta":2},{"choice_id":"HG_VDC_04_E02_C","label":"C","player_text":"Mở hết cửa, để họ tự thử xem có nguy hiểm không.","npc_reply":"Ngươi định dùng thân người khác chứng minh một nguy cơ sao?","affection_delta":-6,"trust_delta":-3}],"repeatable":false,"one_time_per_life":true,"story_reward":false},{"scene_id":"HG_VDC_05_E01","npc_id":"HG_VDC_05","npc_name":"Hứa Mặc","faction":"Vạn Dược Cốc","kind":"event","title":"Bệnh nhân cấp cứu giữa chợ","npc_text":"[Sự kiện] Người bán hàng bất tỉnh ở chợ, xung quanh có đám đông tụ tập.","min_affection":20,"pool_index":1,"choices":[{"choice_id":"HG_VDC_05_E01_A","label":"A","player_text":"Ta bảo đảm hiện trường an toàn, gọi cứu trợ, kiểm tra đáp ứng và hô hấp.","npc_reply":"Ngươi nhớ đúng thứ tự. Hãy hỗ trợ ta giữ lối đi.","affection_delta":9,"trust_delta":5},{"choice_id":"HG_VDC_05_E01_B","label":"B","player_text":"Ta dẹp khoảng trống để Hứa Mặc tiếp cận và hỏi người chứng kiến.","npc_reply":"Cảm ơn. Đám đông đang cản chúng ta.","affection_delta":4,"trust_delta":2},{"choice_id":"HG_VDC_05_E01_C","label":"C","player_text":"Ta ép bệnh nhân uống thuốc lạ ngay.","npc_reply":"Đừng cho người bất tỉnh uống bất cứ thứ gì tùy tiện!","affection_delta":-6,"trust_delta":-3}],"repeatable":false,"one_time_per_life":true,"story_reward":false},{"scene_id":"HG_VDC_05_E02","npc_id":"HG_VDC_05","npc_name":"Hứa Mặc","faction":"Vạn Dược Cốc","kind":"event","title":"Một trang bệnh án thất lạc","npc_text":"[Sự kiện] Hồ sơ ca bệnh biến mất khỏi Đan viện và xuất hiện ở quầy mua bán tin.","min_affection":50,"pool_index":2,"choices":[{"choice_id":"HG_VDC_05_E02_A","label":"A","player_text":"Ta thu hồi hợp lệ, tìm lỗ hổng lưu trữ và thông báo người bị ảnh hưởng.","npc_reply":"Đúng. Quyền riêng tư của họ đã bị hại rồi.","affection_delta":9,"trust_delta":5},{"choice_id":"HG_VDC_05_E02_B","label":"B","player_text":