","label":"A","player_text":"Sơ tán dân, dùng kho linh thạch làm mồi nhử và xin tiếp viện.","npc_reply":"Ta muốn nghe phương án, không phải khẩu hiệu. Ngươi đã cho ta một phương án.","affection_delta":10,"trust_delta":10,"story_flag":"hg_tvt_01_plan_so_tan"},{"choice_id":"HG_TVT_01_S02_B","dialogue_id":"HG_TVT_01_S02","label":"B","player_text":"Giữ kho để tông môn còn sức cứu các làng sau.","npc_reply":"Có lý, nhưng hãy tự tay ghi tên người bị bỏ lại.","affection_delta":-5,"trust_delta":5,"story_flag":"hg_tvt_01_plan_giu_kho"},{"choice_id":"HG_TVT_01_S02_C","dialogue_id":"HG_TVT_01_S02","label":"C","player_text":"Chỉ cứu ai chịu trả công.","npc_reply":"Đại điện này không phải nơi rao giá sinh mạng.","affection_delta":-10,"trust_delta":-10,"story_flag":null}],"next_dialogue_id":"HG_TVT_01_S03","one_time_per_life":true,"scene_id":"HG_TVT_01_S02","kind":"story"},{"dialogue_id":"HG_TVT_01_S03","npc_id":"HG_TVT_01","npc_name":"Lục Thanh Huyền","faction":"Thanh Vân Tông","role":"Chưởng môn","realm":"Hạ Giới","scene_index":3,"stage":"Vết thương","title":"Người đến trước Thiên Biến","min_affection":50,"prerequisite":"HG_TVT_01_S02_completed","npc_text":"Ta từng gặp một kẻ mang dấu ấn tương tự ngươi, từ trước khi Thiên Biến xảy ra. Ngươi muốn biết điều gì trước?","choices":[{"choice_id":"HG_TVT_01_S03_A","dialogue_id":"HG_TVT_01_S03","label":"A","player_text":"Người ấy có còn sống và có cần giúp đỡ không?","npc_reply":"Ngươi hỏi về con người trước bí mật. Ta ghi nhận.","affection_delta":10,"trust_delta":5,"story_flag":"hg_tvt_01_lore_tien_khach"},{"choice_id":"HG_TVT_01_S03_B","dialogue_id":"HG_TVT_01_S03","label":"B","player_text":"Dấu ấn của người ấy khác ta ở đâu?","npc_reply":"Câu hỏi sắc bén. Có lẽ nên đưa ngươi đến gặp Mạc trưởng lão.","affection_delta":5,"trust_delta":10,"story_flag":"hg_tvt_01_lore_dau_an"},{"choice_id":"HG_TVT_01_S03_C","dialogue_id":"HG_TVT_01_S03","label":"C","player_text":"Ngài giấu tin lâu như vậy, hẳn đang phản bội chúng ta.","npc_reply":"Ta có