","realm":"Hạ Giới","scene_index":3,"stage":"Vết thương","title":"Sân đấu ngoại môn","min_affection":50,"prerequisite":"HG_HSM_03_S02_completed","npc_text":"Ta thắng một trận nhỏ. Có nên tiếp tục đấu với kẻ mạnh hơn hẳn để được chú ý không?","choices":[{"choice_id":"HG_HSM_03_S03_A","dialogue_id":"HG_HSM_03_S03","label":"A","player_text":"Luyện thêm, chọn trận phù hợp và giữ sức tìm em gái.","npc_reply":"Ta suýt quên vì sao mình phải sống.","affection_delta":10,"trust_delta":10,"story_flag":"hg_hsm_03_quest_luyen_the"},{"choice_id":"HG_HSM_03_S03_B","dialogue_id":"HG_HSM_03_S03","label":"B","player_text":"Đấu nếu có đường lui và người cứu hộ.","npc_reply":"Ta sẽ đặt điều kiện trước, không liều mù quáng.","affection_delta":5,"trust_delta":10,"story_flag":null},{"choice_id":"HG_HSM_03_S03_C","dialogue_id":"HG_HSM_03_S03","label":"C","player_text":"Thua cũng được, miễn nổi tiếng.","npc_reply":"Danh tiếng không đưa ta đến chỗ em ấy.","affection_delta":-5,"trust_delta":-5,"story_flag":null}],"next_dialogue_id":"HG_HSM_03_S04","one_time_per_life":true,"scene_id":"HG_HSM_03_S03","kind":"story"},{"dialogue_id":"HG_HSM_03_S04","npc_id":"HG_HSM_03","npc_name":"A Cửu","faction":"Huyết Sát Môn","role":"Đệ tử ngoại môn, người Trái Đất","realm":"Hạ Giới","scene_index":4,"stage":"Lựa chọn","title":"Bàn tay buông ra","min_affection":80,"prerequisite":"HG_HSM_03_S03_completed","npc_text":"Ngày Thiên Biến, ta đã sợ đến mức buông tay em gái. Ngươi có khinh ta không?","choices":[{"choice_id":"HG_HSM_03_S04_A","dialogue_id":"HG_HSM_03_S04","label":"A","player_text":"Ngươi từng sợ hãi. Điều đó không khiến ngươi mất quyền tìm và xin lỗi em.","npc_reply":"Ta... đã chờ ai đó nói câu này rất lâu.","affection_delta":10,"trust_delta":10,"story_flag":"hg_hsm_03_lore_buong_tay"},{"choice_id":"HG_HSM_03_S04_B","dialogue_id":"HG_HSM_03_S04","label":"B","player_text":"Ta không phán xét chuyện mình chưa trải qua.","npc_reply":"Ừ. Ngươi chịu ngồi nghe đã là đủ.","affection_delta":5,"trust_delta":10,"story_flag":null},{"choice_id":"HG_HSM_03_S04_C","dialogue_id":"HG_HSM_03_S04","label":"C","player_text":"Nếu là ta, ta không bao giờ buông tay.","npc_reply":"Ngươi có chắc không? Ta đã từng chắc như vậy.","affection_delta":-10,"trust_delta":-10,"story_flag":null}],"next_dialogue_id":"HG_HSM_03_S05","one_time_per_life":true,"scene_id":"HG_HSM_03_S04","kind":"story"},{"dialogue_id":"HG_HSM_03_S05","npc_id":"HG_HSM_03","npc_name":"A Cửu","faction":"Huyết Sát Môn","role":"Đệ tử ngoại môn, người Trái Đất","realm":"Hạ Giới","scene_index":5,"stage":"Kết cục/mở tuyến","title":"Cấm pháp trong hộp sắt","min_affection":100,"prerequisite":"HG_HSM_03_S04_completed","npc_text":"Có cấm pháp giúp mạnh nhanh, nhưng sẽ ăn mòn thần trí. Ta nên dùng để tìm em không?","choices":[{"choice_id":"HG_HSM_03_S05_A","dialogue_id":"HG_HSM_03_S05","label":"A","player_text":"Đừng đánh mất chính mình. Ta sẽ giúp tìm manh mối khác.","npc_reply":"Nếu còn cách khác, ta muốn thử trước.","affection_delta":10,"trust_delta":10,"story_flag":"hg_hsm_03_ending_tu_choi_cam_phap"},{"choice_id":"HG_HSM_03_S05_B","dialogue_id":"HG_HSM_03_S05","label":"B","player_text":"Hãy hỏi Hắc Đồng và Dược Cốc xem có thể giảm tác hại không.","npc_reply":"Ít ra ngươi không xem lời quảng cáo là chân lý.","affection_delta":5,"trust_delta":10,"story_flag":"hg_hsm_03_ending_nghien_cuu_cam_phap"},{"choice_id":"HG_HSM_03_S05_C","dialogue_id":"HG_HSM_03_S05","label":"C","player_text":"Dùng ngay. Mạnh rồi sẽ giải quyết tất cả.","npc_reply":"Ta đã muốn nghe câu ấy... Nhưng sao nghe xong lại thấy sợ hơn?","affection_delta":5,"trust_delta":-10,"story_flag":"hg_hsm_03_ending_dung_cam_phap"}],"next_dialogue_id":null,"one_time_per_life":true,"scene_id":"HG_HSM_03_S05","kind":"story"},{"dialogue_id":"HG_HSM_04_S01","npc_id":"HG_HSM_04","npc_name":"Tần Vô Sinh","faction":"Huyết Sát Môn","role":"Đại trưởng lão","realm":"Hạ Giới","scene_index":1,"stage":"Gặp gỡ","title":"Món nợ đầu tiên","min_affection":0,"prerequisite":"npc_met","npc_text":