a ngươi có thể vượt cả ta đấy.","affection_delta":5,"trust_delta":-10,"story_flag":null}],"next_dialogue_id":"HG_HSM_04_S03","one_time_per_life":true,"scene_id":"HG_HSM_04_S02","kind":"story"},{"dialogue_id":"HG_HSM_04_S03","npc_id":"HG_HSM_04","npc_name":"Tần Vô Sinh","faction":"Huyết Sát Môn","role":"Đại trưởng lão","realm":"Hạ Giới","scene_index":3,"stage":"Vết thương","title":"Lời mời vào nội điện","min_affection":50,"prerequisite":"HG_HSM_04_S02_completed","npc_text":"Theo phe ta, ngươi sẽ có công pháp và tài nguyên. Đổi lại, chớ hỏi về Huyết Ấn.","choices":[{"choice_id":"HG_HSM_04_S03_A","dialogue_id":"HG_HSM_04_S03","label":"A","player_text":"Ta chỉ nhận nhiệm vụ rõ ràng; phần liên quan sinh mạng phải được biết.","npc_reply":"Khó điều khiển. Nhưng ta biết ngươi không bán lời tùy tiện.","affection_delta":-5,"trust_delta":10,"story_flag":"hg_hsm_04_route_khong_ban_minh"},{"choice_id":"HG_HSM_04_S03_B","dialogue_id":"HG_HSM_04_S03","label":"B","player_text":"Ta xem điều kiện bằng văn bản rồi quyết định.","npc_reply":"Có đầu óc giao dịch. Ta chờ câu trả lời.","affection_delta":5,"trust_delta":5,"story_flag":null},{"choice_id":"HG_HSM_04_S03_C","dialogue_id":"HG_HSM_04_S03","label":"C","player_text":"Chỉ cần nhiều tài nguyên, bảo ta làm gì cũng được.","npc_reply":"Một con dao rẻ tiền. Dùng xong là bỏ.","affection_delta":10,"trust_delta":-10,"story_flag":"hg_hsm_04_route_bi_loi_dung"}],"next_dialogue_id":"HG_HSM_04_S04","one_time_per_life":true,"scene_id":"HG_HSM_04_S03","kind":"story"},{"dialogue_id":"HG_HSM_04_S04","npc_id":"HG_HSM_04","npc_name":"Tần Vô Sinh","faction":"Huyết Sát Môn","role":"Đại trưởng lão","realm":"Hạ Giới","scene_index":4,"stage":"Lựa chọn","title":"Một đội quân không sợ chết","min_affection":80,"prerequisite":"HG_HSM_04_S03_completed","npc_text":"Nếu Huyết Ấn khiến môn nhân phục tùng tuyệt đối, chẳng phải chiến lực tăng gấp bội sao?","choices":[{"choice_id":"HG_HSM_04_S04_A","dialogue_id":"HG_HSM_04_S04","label":"A","player_text":"Phục tùng 