ction":50,"prerequisite":"HG_TL_02_S02_completed","npc_text":"Đường ngắn có yêu thú, đường vòng tốn nhiều phí. Ngươi khuyên đoàn buôn chọn gì?","choices":[{"choice_id":"HG_TL_02_S03_A","dialogue_id":"HG_TL_02_S03","label":"A","player_text":"Ước lượng rủi ro, hỏi hộ vệ và chỉ đi đường ngắn nếu có phương án an toàn.","npc_reply":"Một đồng kiếm thêm không đáng đổi bằng một mạng.","affection_delta":10,"trust_delta":10,"story_flag":"hg_tl_02_quest_tuyen_thuong"},{"choice_id":"HG_TL_02_S03_B","dialogue_id":"HG_TL_02_S03","label":"B","player_text":"Đi đường vòng và báo rõ phí tăng cho khách.","npc_reply":"Chậm nhưng chắc. Ta còn muốn mở quán năm sau.","affection_delta":5,"trust_delta":10,"story_flag":null},{"choice_id":"HG_TL_02_S03_C","dialogue_id":"HG_TL_02_S03","label":"C","player_text":"Giấu nguy hiểm để nhận thêm hợp đồng.","npc_reply":"Ta kiếm tiền bằng bán hàng, không bán mạng người.","affection_delta":-10,"trust_delta":-10,"story_flag":null}],"next_dialogue_id":"HG_TL_02_S04","one_time_per_life":true,"scene_id":"HG_TL_02_S03","kind":"story"},{"dialogue_id":"HG_TL_02_S04","npc_id":"HG_TL_02","npc_name":"Bạch Tiểu Ngư","faction":"Trung lập","role":"Thương nhân lang bạt","realm":"Hạ Giới","scene_index":4,"stage":"Lựa chọn","title":"Tin tức hay bí mật","min_affection":80,"prerequisite":"HG_TL_02_S03_completed","npc_text":"Ta biết nơi người ta đồn có cổ vật liên quan Thiên Mệnh. Ngươi có muốn mua tin?","choices":[{"choice_id":"HG_TL_02_S04_A","dialogue_id":"HG_TL_02_S04","label":"A","player_text":"Chỉ mua manh mối kiểm chứng được, không đòi mua vật phẩm nhiệm vụ bí ẩn.","npc_reply":"Đúng. Ta bán đường đi, không bán thứ chưa từng thuộc về ta.","affection_delta":10,"trust_delta":10,"story_flag":"hg_tl_02_lore_gioi_han_thuong_hoi"},{"choice_id":"HG_TL_02_S04_B","dialogue_id":"HG_TL_02_S04","label":"B","player_text":"Ta muốn biết nguồn tin đáng tin đến mức nào trước khi trả.","npc_reply":"Khách tỉnh táo thì ta đỡ mất thời gian cãi nhau.","affection_delta":5,"trust_delta":10,"story_flag":null},{"choice_id":"HG_TL_02_S04_C","dialogue_id":"HG_TL_02_S04","label":"C","player_text":"Bán thẳng cổ vật ẩn cho ta, giá nào cũng trả.","npc_reply":"Có tiền không có nghĩa mua được mọi thứ.","affection_delta":-5,"trust_delta":-10,"story_flag":null}],"next_dialogue_id":"HG_TL_02_S05","one_time_per_life":true,"scene_id":"HG_TL_02_S04","kind":"story"},{"dialogue_id":"HG_TL_02_S05","npc_id":"HG_TL_02","npc_name":"Bạch Tiểu Ngư","faction":"Trung lập","role":"Thương nhân lang bạt","realm":"Hạ Giới","scene_index":5,"stage":"Kết cục/mở tuyến","title":"Thương hội qua ba giới","min_affection":100,"prerequisite":"HG_TL_02_S04_completed","npc_text":"Nếu thương hội của ta lớn đến Linh Giới, điều gì tuyệt đối không được đánh mất?","choices":[{"choice_id":"HG_TL_02_S05_A","dialogue_id":"HG_TL_02_S05","label":"A","player_text":"Chữ tín và quy tắc không ép người khó khăn vào đường cùng.","npc_reply":"Được! Ngươi còn nhớ cô hàng rong năm ấy là tốt.","affection_delta":10,"trust_delta":10,"story_flag":"hg_tl_02_route_thuong_hoi_chu_tin"},{"choice_id":"HG_TL_02_S05_B","dialogue_id":"HG_TL_02_S05","label":"B","player_text":"Sổ sách minh bạch và mạng lưới vận chuyển an toàn.","npc_reply":"Ta sẽ thuê người giỏi hơn mình, nhưng tự tay kiểm sổ.","affection_delta":10,"trust_delta":10,"story_flag":"hg_tl_02_route_thuong_hoi_min_bach"},{"choice_id":"HG_TL_02_S05_C","dialogue_id":"HG_TL_02_S05","label":"C","player_text":"Độc quyền hết nguồn thuốc rồi nâng giá vô hạn.","npc_reply":"Kiếm nhiều vậy để làm gì nếu thiên hạ chỉ mong ta chết?","affection_delta":-10,"trust_delta":-10,"story_flag":null}],"next_dialogue_id":null,"one_time_per_life":true,"scene_id":"HG_TL_02_S05","kind":"story"},{"dialogue_id":"HG_TL_03_S01","npc_id":"HG_TL_03","npc_name":"Ông Lão Vô Danh","faction":"Trung lập","role":"Người chèo đò","realm":"Hạ Giới","scene_index":1,"stage":"Gặp gỡ","title":"Một đồng tiền qua sông","min_affection":0,"prerequisite":"npc_met","npc_text":"Khách muốn qua sông mà không có tiền