04","npc_name":"Cao Thành","faction":"Trung lập","role":"Người Trái Đất, thủ lĩnh nhóm tự trị","realm":"Hạ Giới","scene_index":1,"stage":"Gặp gỡ","title":"Luật mới của kẻ mạnh","min_affection":0,"prerequisite":"npc_met","npc_text":"Ở Trái Đất ta phải tuân luật. Ở đây sức mạnh tự đặt luật. Ngươi thấy đây là cơ hội hay tai họa?","choices":[{"choice_id":"HG_TL_04_S01_A","dialogue_id":"HG_TL_04_S01","label":"A","player_text":"Là cơ hội xây cộng đồng an toàn, nếu quyền lực có giới hạn.","npc_reply":"Ngươi nói như một người quản trị. Ta sẽ nghe thêm.","affection_delta":5,"trust_delta":10,"story_flag":null},{"choice_id":"HG_TL_04_S01_B","dialogue_id":"HG_TL_04_S01","label":"B","player_text":"Kẻ mạnh nên được quyền lãnh đạo nếu chứng minh được năng lực.","npc_reply":"Ha! Cuối cùng có kẻ thực tế.","affection_delta":10,"trust_delta":0,"story_flag":null},{"choice_id":"HG_TL_04_S01_C","dialogue_id":"HG_TL_04_S01","label":"C","player_text":"Cứ thống trị hết, ai phản đối thì xử.","npc_reply":"Nhiệt tình đấy, nhưng kẻ nóng đầu thường phá kế hoạch.","affection_delta":5,"trust_delta":-10,"story_flag":null}],"next_dialogue_id":"HG_TL_04_S02","one_time_per_life":true,"scene_id":"HG_TL_04_S01","kind":"story"},{"dialogue_id":"HG_TL_04_S02","npc_id":"HG_TL_04","npc_name":"Cao Thành","faction":"Trung lập","role":"Người Trái Đất, thủ lĩnh nhóm tự trị","realm":"Hạ Giới","scene_index":2,"stage":"Làm quen","title":"Kho dự trữ của người lạc giới","min_affection":20,"prerequisite":"HG_TL_04_S01_completed","npc_text":"Nhóm ta có lương thực và linh thạch dự trữ. Người ngoài xin cứu tế. Ta phải lấy phí không?","choices":[{"choice_id":"HG_TL_04_S02_A","dialogue_id":"HG_TL_04_S02","label":"A","player_text":"Có định mức minh bạch và quỹ khẩn cấp, tránh người yếu chết đói.","npc_reply":"Một tổ chức sống lâu cần sổ sách. Ngươi có ích.","affection_delta":5,"trust_delta":10,"story_flag":"hg_tl_04_quest_quy_du_tru"},{"choice_id":"HG_TL_04_S02_B","dialogue_id":"HG_TL_04_S02","label":"B","player_text":"Thu 